const app=document.querySelector('#app');
function figure(id,place){const box=document.createElement('div');box.className='minifigure-motion '+place;box.setAttribute('aria-hidden','true');const img=document.createElement('img');img.src='./assets/minifigure-'+id+'.svg';img.alt='';img.width=320;img.height=140;box.append(img);return box}
function decorate(){if(!app.querySelector('.hero')){document.querySelector('.header-walk')?.remove();return}if(app.querySelector('.minifigure-motion'))return;document.querySelector('.header-walk')?.remove();document.querySelector('header .brand').after(figure('walk','header-walk'));const notice=app.querySelector('.notice');notice.insertBefore(figure('chase','notice-chase'),notice.querySelector('a'));const heading=app.querySelector('.section-heading');heading.classList.add('home-featured-heading');heading.insertBefore(figure('photo','featured-photo'),heading.querySelector(':scope>a'));const bath=document.createElement('div');bath.className='home-bath-wrap';bath.append(figure('bath','service-bath'));app.querySelector('.benefits').before(bath)}
new MutationObserver(decorate).observe(app,{childList:true});decorate();
